/**
 * Implements in memory building of the tar archive from a given module folder.
 *
 * NOTE: There is an intentional design decision not to run npm install here.
 *       We simply bundle the output of the module.
 *
 * (too many missing interfaces...)
 * @flow
 */

import computeHash from './compute_hash';
import createLog from 'debug';
import * as pkg from './package';
import fs from 'fs';
import path from 'path';
import tmp from './tmp';
import run from './run';
import eventToPromise from 'event-to-promise';
import {spawn} from 'child_process';
import {exec} from 'mz/child_process';

import type {PackageJSON} from '../package';
import type {Readable} from 'stream';

const log = createLog('bundle');

export const METADATA_PATH = 'node_modules/.node_modules_cache.json';

async function findTar() {
  let tarPromise = exec(`which tar`);
  let gtarPromise = exec(`which gtar`);

  try {
    let [result] = await gtarPromise;
    return result.trim();
  } catch(err) {
    // nothing we keep trying if gtar is missing.
  }

  let [result] = await tarPromise;
  return result.trim();
}

export default async function(
  modulePkg: PackageJSON,
  modulePath: string,
): Readable {
  let target = tmp();

  // move package.json over...
  fs.writeFileSync(path.join(target, 'package.json'), JSON.stringify(modulePkg));

  // Move npmrc over if it exists...
  let npmrcPath = path.join(modulePath, '.npmrc');
  if (fs.existsSync(npmrcPath)) {
    let npmrc = fs.readFileSync(npmrcPath);
    fs.writeFileSync(path.join(target, '.npmrc'), npmrc);
  }
  await run(`npm i --ignore-scripts`, { cwd: target });

  let nodeModules = path.join(target, 'node_modules');
  let metadata = {
    hash: computeHash(modulePkg),
    dependencies: pkg.dependencies(modulePkg),
  };
  fs.writeFileSync(path.join(target, METADATA_PATH), JSON.stringify(metadata));

  let tar = await findTar();
  log('using tar', tar);

  // spawn the tar process...
  let proc = spawn(tar, ['-cz', 'node_modules'], {
    cwd: target
  });
  return proc.stdout;
}
